import{_ as r,a0 as a,w as i,s as l,ao as u,I as n,x as t,a1 as o,A as p}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"閉源優於開源的七個緣由？是這樣嗎？ | LCTT x X-CMD","titleTemplate":false,"description":"閉源優於開源的七個緣由？是這樣嗎？ | LCTT (201311) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"閉源優於開源的七個緣由？是這樣嗎？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"閉源優於開源的七個緣由？是這樣嗎？ | LCTT (201311) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201311/Seven reasons why closed source is better than open source, or so it seems","title":"閉源優於開源的七個緣由？是這樣嗎？","tag":"201311","desc":""},"relativePath":"201311/Seven reasons why closed source is better than open source, or so it seems.md","filePath":"[post].md"}'),d={name:"201311/Seven reasons why closed source is better than open source, or so it seems.md"};function m(T,e,f,_,b,g){const s=a("Link");return i(),l("div",null,[e[11]||(e[11]=u('<h1 id="閉源優於開源的七個緣由-是這樣嗎" tabindex="-1">閉源優於開源的七個緣由？是這樣嗎？ <a class="header-anchor" href="#閉源優於開源的七個緣由-是這樣嗎" aria-label="Permalink to “閉源優於開源的七個緣由？是這樣嗎？”">​</a></h1><p><img src="http://opensource.com/sites/default/files/imagecache/image-full-size/images/business/BUSINESS_asusual_deadend.png" alt=""></p><p>這看起來似乎挺奇怪的，因為這樣的觀點來竟然自於OpenLogic的創辦人，而該公司專注於在開源領域提供幫助。 但是事實上，閉源在某些情況下優於開源。</p><p>針對閉源……</p><p>###1. 出了問題，不用自己搞定</p><p>只要是軟件，難保不出問題。要是開源軟件出了這事兒，要麼你自己，要麼某個欠你人情債的工程師，總得有個人要花費時間排除bug。通覽代碼，求助於開源社區或者開源軟件的供應商，通過這些手段來解決問題。</p><p>但是閉源呢，一旦你確定開發商代碼出了問題，ok，你的工作到此為止！ 你只需發個文件，等着就行了。當然，可能會等上幾個月或者幾年，問題才能得到解決，更甚者永遠得不到答覆。但是除此之外，你還能做什麼呢。 把問題踢回去，放鬆，期待最好的解決方案，僅此而已。</p><p>###2. 不必擔心貢獻迴流到社區</p><p>如果用的是開源軟件， 很有可能， 你解決了一個bug或者做出了改善，之後你的代碼就會進入到社區，隨着時間的推移從而幫助測試或者維護。</p><p>閉源就不同了，你根本用不着給任何人做任何事情。當然，那是因為你接觸不到代碼，所以也修改不了，但是你可以針對遇到的問題創建自己的解決方案。你可以一直只針對同一個問題，改善再改善，一個版本接着一個版本，至少用不着跟社區打交道，為其他人提供更好的解決方法。</p><p>###3. 你不必考慮開源許可條款及規定事宜</p><p>對於開源，你必須遵循所使用的組件的許可條款。例如，想要搞明白Apache軟件許可證和GPL之間的區別與聯繫，是需要花費一定的時間的。使用哪一種許可證取決於你所用的開源組件以及你如何使用這些組件（發佈給第三方或者內部使用），據此都有不同的許可證可供應用（可附加到文檔中進行説明）。</p><p>像OpenLogic這樣的公司可以很容易地理解並遵守開源許可，但是針對閉源，你大可不必擔心這類事情！你的供應商的許可協議把有關軟件的所有的權利都收走了，如果沒有你的公司的律師明確同意的情況下，你幾乎是不可能的想以別的方式使用這些軟件，想都不要想。當然，你還得考慮許可證數量、突如其來的軟件合規性審計、隨着時間的推移而惡化的條款、幾乎難以理解的法律術語，但至少你不必瞭解如何使用開源組件。</p><p>###4. 你用不着為每個組件在眾多選項中進行選擇</p><p>針對資料庫，Web服務器，應用服務器，編程語言，圖形用户界面框架，類似的方面等等，開源都提供了大量的解決方案。在每一個特定的領域，你都可以找到運用不同的架構方法，使用各種語言構建的健壯的成品。找一款功能相似的工具很容易，這些工具都針對不同的使用場合進行了優化（性能、可擴展性、簡潔之間的比較）。為了確信一個工具軟件在既定場合下功能夠滿足需求，可以下載下來，試用一下。</p><p>使用閉源軟件的話，你就用不着對付那麼多的選擇。你只需要在每個領域探索兩三個大廠商提供的產品。如果供應商沒有提供免費試用版本，或者很難説服你為試用品買單，甚至根本不和你簽署試用協議，那你就節省時間了。</p><p>###5. 你不必四處找幻燈片</p><p>如果打算找一些軟件的會議簡報，架構圖表，截圖，以及其他相關的文檔，這需要花費一定的時間。使用開源軟件，你得讀百科，訪問論壇，還有郵件列表，才能獲取到你需要的相關組件的信息。</p><p>使用閉源軟件，一通電話就足夠了，只需坐在自己舒適的辦公室，會有西裝革履的專業人士把PowerPoint演示文稿寄送到你的面前。當然，在你提供自己的聯繫方式之前，銷售人員是不會給你打電話的。這樣看來，至少自己沒必要在網上搜索帶有漂亮的圖形的PPT。</p><p>###6. 你無需到處尋求技術支持</p><p>你可以得到來自開源社區，自己的工程師，或專業開源組織的幫助。這可能需要一些時間，以決定是否要服務等級協議（SLA）的支持，以便於在保證的時間內得到答覆，就像從OpenLogic那裏獲得幫助一樣，或者如果你可以自由的發問題到郵件列表，自己解決。</p><p>閉源就不同了，你根本不需要擔憂從哪獲得幫助。而且，你可能根本用不着和工程師當面交談，只需要知道給誰打電話就OK了。</p><p>###7. 認輸就行了</p><p>開源軟件，總會有辦法解決問題，打補丁，改善，強化，重構，升級，或者重寫。沒可能跟閉源那樣，甩手走開。當然，你可以謾罵開發出這個導致問題的軟件的社區，但是你仍然可以解決問題，從社區或者組織那裏獲得幫助，或者自己動手解決。 而對於商業供應商，那就遠不能滿足於罵一頓和花費一天的時間來找他們。</p><p>嗯，你都瞭解了。為甚麼閉源優於開源的幾條緣由。你還有要補充的嗎？</p><hr>',26)),n("p",null,[e[1]||(e[1]=t("via: ",-1)),o(s,{href:"http://opensource.com/business/13/10/seven-reasons-closed-better-than-open-source"},{default:p(()=>[...e[0]||(e[0]=[t("http://opensource.com/business/13/10/seven-reasons-closed-better-than-open-source",-1)])]),_:1})]),n("p",null,[e[4]||(e[4]=t("譯者：",-1)),o(s,{href:"https://github.com/l3b2w1"},{default:p(()=>[...e[2]||(e[2]=[t("l3b2w1",-1)])]),_:1}),e[5]||(e[5]=t(" 校對：",-1)),o(s,{href:"https://github.com/wxy"},{default:p(()=>[...e[3]||(e[3]=[t("wxy",-1)])]),_:1})]),n("p",null,[e[8]||(e[8]=t("本文由 ",-1)),o(s,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...e[6]||(e[6]=[t("LCTT",-1)])]),_:1}),e[9]||(e[9]=t(" 原創翻譯，",-1)),o(s,{href:"http://linux.cn/"},{default:p(()=>[...e[7]||(e[7]=[t("Linux中國",-1)])]),_:1}),e[10]||(e[10]=t(" 榮譽推出",-1))])])}const c=r(d,[["render",m]]);export{L as __pageData,c as default};
